import React from "react";

export default function Field({ label, value, onChange }) {
  return (
    <div>
      <label htmlFor="russian-word">{label}</label>
      <input
        id="russian-word"
        className="input"
        type="text"
        lang="ru"
        value={value}
        placeholder="Например, кот"
        onChange={e => onChange(e.target.value)}
      />
    </div>
  );
}
