import React, { useEffect, useState } from "react";
import axios from "axios";

const DICTIONARY_URL = "https://dictionary.yandex.net/api/v1/dicservice.json/lookup";

// Вставьте личный НОВЫЙ ключ Yandex Dictionary API (не Yandex Cloud Translate).
const YANDEX_DICTIONARY_KEY = "dict.1.1.20261027T065426Z.a1ccfd2b2228b152.3faa9d30226f1c73bf49f26225b5e98823bd97f7";

const doTranslation = async (input, languageCode, cancelToken) => {
  // Yandex Dictionary: lookup?key=...&lang=ru-en&text=...
  // Axios сам кодирует параметры, в том числе русские буквы.
  const { data } = await axios.get(DICTIONARY_URL, {
    params: {
      key: YANDEX_DICTIONARY_KEY,
      lang: `ru-${languageCode}`,
      text: input
    },
    cancelToken: cancelToken.token
  });

  // Структура ответа из методички: data.def[0].tr[0].text
  if (data && data.def && data.def.length &&
      data.def[0].tr && data.def[0].tr.length) {
    return data.def[0].tr[0].text;
  }
  return "";
};

export default function Translate({ text, language }) {
  const [translated, setTranslated] = useState("");
  const [status, setStatus] = useState("");

  useEffect(() => {
    const word = text.trim();
    setTranslated("");
    setStatus("");
    if (!word) return undefined;

    if (!/^[а-яё]+(?:-[а-яё]+)*$/i.test(word)) {
      setStatus("Введите одно русское слово.");
      return undefined;
    }

    if (YANDEX_DICTIONARY_KEY === "ВСТАВЬТЕ_НОВЫЙ_КЛЮЧ_СЛОВАРЯ") {
      setStatus("Добавьте ключ Yandex Dictionary в translate.js.");
      return undefined;
    }

    const cancelToken = axios.CancelToken.source();
    // Чтобы не обращаться к API на каждую введённую букву немедленно.
    const timer = setTimeout(() => {
      doTranslation(word, language, cancelToken)
        .then(result => {
          setTranslated(result);
          if (!result) setStatus("Для этого слова перевод в словаре не найден.");
        })
        .catch(error => {
          if (!axios.isCancel(error)) {
            setStatus("Ошибка обращения к Yandex Dictionary API.");
          }
        });
    }, 400);

    return () => {
      clearTimeout(timer);
      cancelToken.cancel("Введено новое слово");
    };
  }, [text, language]);

  return (
    <div className="translation">
      <h1 className="title" aria-live="polite">{translated}</h1>
      {status && <p role="status">{status}</p>}
    </div>
  );
}
